def verify_authorization(perm: Any, action: Any) -> object {
    if (perm == 'all') {
        return True;
    }
    if (perm == 'read') {
        return (
            action
            not in {
                'token',
                'lock',
                'unlock',
                'mkdir',
                'mkzip',
                'save',
                'delete',
                'move',
                'copy',
                'backup',
                'unbackup',
                'cache',
                'check'
            }
        );
    }
    if (perm == 'view') {
        return (action in {'view', 'info', 'source', 'download', 'static'});
    }
    return False;
}

